import std/[syncio, strutils, tables, sets, algorithm]

proc main =
  let text = "the cat sat on the mat the cat ran the dog sat on the log dog dog"
  var freq = initTable[string, int]()
  for w in text.splitWhitespace():
    freq[w] = freq.getOrDefault(w) + 1

  # deterministic: collect keys and sort
  var keys: seq[string] = @[]
  for k in freq.keys:
    keys.add(k)
  sort(keys, proc(a, b: string): int = cmp(a, b))

  echo "word frequencies:"
  for k in keys:
    echo "  ", k, " = ", freq.getOrDefault(k)

  # dedup preserving sorted order via HashSet
  var seen = initHashSet[string]()
  var uniq: seq[string] = @[]
  for w in text.splitWhitespace():
    if not seen.contains(w):
      seen.incl(w)
      uniq.add(w)
  sort(uniq, proc(a, b: string): int = cmp(a, b))
  echo "unique words: ", uniq.len

  # set intersection
  var setA = initHashSet[string]()
  for w in "the cat dog fish".splitWhitespace(): setA.incl(w)
  var setB = initHashSet[string]()
  for w in "dog fish bird the".splitWhitespace(): setB.incl(w)
  let inter = intersection(setA, setB)
  var interList: seq[string] = @[]
  for w in inter: interList.add(w)
  sort(interList, proc(a, b: string): int = cmp(a, b))
  echo "intersection: ", interList.len, " ->"
  for w in interList: echo "  ", w

main()

import std/[syncio, algorithm]

proc seqStr(a: seq[int]): string =
  result = "["
  for i in 0 ..< a.len:
    if i > 0: result.add(", ")
    result.add($a[i])
  result.add("]")

proc binarySearch(a: seq[int], key: int): int =
  var lo = 0
  var hi = a.len - 1
  while lo <= hi:
    let mid = (lo + hi) div 2
    if a[mid] == key:
      return mid
    elif a[mid] < key:
      lo = mid + 1
    else:
      hi = mid - 1
  return -1

proc main =
  var data = @[42, 7, 13, 99, 1, 56, 23, 8, 77, 34, 2, 65]
  echo "original: ", seqStr(data)
  sort(data, proc(a, b: int): int = cmp(a, b))
  echo "ascending: ", seqStr(data)
  sort(data, proc(a, b: int): int = cmp(b, a))
  echo "descending: ", seqStr(data)

  # re-sort ascending for search
  sort(data, proc(a, b: int): int = cmp(a, b))
  for key in [1, 23, 99, 100, 8, 5]:
    echo "search ", key, " -> index ", binarySearch(data, key)

  # verify sorted
  var ok = true
  for i in 1 ..< data.len:
    if data[i-1] > data[i]: ok = false
  echo "isSorted=", ok

main()

import std/[syncio, tables]

proc makeCounter(start: int): (proc(): int {.closure.}) =
  var count = start
  result = proc(): int {.closure.} =
    inc count
    return count

proc makeMemoFib(): (proc(n: int): int {.closure.}) =
  var cache = initTable[int, int]()
  proc fibRec(n: int): int {.closure.} =
    if n < 2: return n
    let hit = cache.getOrDefault(n, -1)
    if hit >= 0: return hit
    let v = fibRec(n - 1) + fibRec(n - 2)
    cache[n] = v
    return v
  result = fibRec

proc main =
  let c1 = makeCounter(0)
  let c2 = makeCounter(100)
  echo "c1: ", c1(), " ", c1(), " ", c1()
  echo "c2: ", c2(), " ", c2()
  echo "c1 again: ", c1()

  let fib = makeMemoFib()
  var line = "fib:"
  for n in [0, 1, 5, 10, 20, 30]:
    line.add(" ")
    line.add($fib(n))
  echo line

  # recursion: classic factorial + Ackermann-ish bounded
  proc fact(n: int): int =
    if n <= 1: return 1
    return n * fact(n - 1)
  echo "5! = ", fact(5)
  echo "10! = ", fact(10)

main()

import std/[syncio]

type
  ParseFailure = distinct int32

proc code(e: ParseFailure): int32 = int32(e)

# deep proc raises
proc validateDigit(c: char): int {.raises: ParseFailure.} =
  if c < '0' or c > '9':
    raise ParseFailure(int32(ord(c)))
  return ord(c) - ord('0')

# middle frame, propagates
proc parseNumber(s: string): int {.raises: ParseFailure.} =
  result = 0
  for ch in s:
    result = result * 10 + validateDigit(ch)

# outer frame catches
proc tryParse(s: string): string =
  try:
    let v = parseNumber(s)
    return "ok:" & $v
  except ParseFailure as e:
    return "bad char code:" & $code(e)

proc guarded(fail: bool, log: var seq[string]) {.raises: ParseFailure.} =
  try:
    log.add("enter")
    if fail: raise ParseFailure(99)
    log.add("normal")
  finally:
    log.add("finally")

proc main =
  echo tryParse("12345")
  echo tryParse("12a45")
  echo tryParse("0")

  # finally runs on both success and failure paths
  var log: seq[string] = @[]
  try:
    guarded(false, log)
  except ParseFailure:
    log.add("caught")
  try:
    guarded(true, log)
  except ParseFailure:
    log.add("caught")

  var line = "log:"
  for s in log:
    line.add(" ")
    line.add(s)
  echo line

main()

import std/[syncio]
{.feature: "lenientnils".}

type
  Node = ref object
    val: int
    next: Node

  TreeNode = ref object
    key: int
    left, right: TreeNode

proc buildList(vals: seq[int]): Node =
  result = nil
  var i = vals.len - 1
  while i >= 0:
    let n = Node(val: vals[i], next: result)
    result = n
    dec i

proc sumList(head: Node): int =
  result = 0
  var cur = head
  while cur != nil:
    result = result + cur.val
    cur = cur.next

proc listStr(head: Node): string =
  result = ""
  var cur = head
  var first = true
  while cur != nil:
    if not first: result.add("->")
    result.add($cur.val)
    first = false
    cur = cur.next

proc insert(root: TreeNode, key: int): TreeNode =
  if root == nil:
    return TreeNode(key: key, left: nil, right: nil)
  if key < root.key:
    root.left = insert(root.left, key)
  elif key > root.key:
    root.right = insert(root.right, key)
  return root

proc inorder(root: TreeNode, acc: var seq[int]) =
  if root == nil: return
  inorder(root.left, acc)
  acc.add(root.key)
  inorder(root.right, acc)

proc main =
  let lst = buildList(@[3, 1, 4, 1, 5, 9, 2, 6])
  echo "list: ", listStr(lst)
  echo "sum: ", sumList(lst)

  var root: TreeNode = nil
  for k in [50, 30, 70, 20, 40, 60, 80, 30]:
    root = insert(root, k)
  var acc: seq[int] = @[]
  inorder(root, acc)
  var line = "bst inorder:"
  for v in acc:
    line.add(" ")
    line.add($v)
  echo line

  # revisit a shared sub-structure (DAG, not a cycle) — safe under ARC
  let shared = buildList(@[100, 200])
  let g1 = Node(val: 1, next: shared)
  let g2 = Node(val: 2, next: shared)
  echo "g1 sum: ", sumList(g1)
  echo "g2 sum: ", sumList(g2)

main()

import std/[syncio]

proc addChecked(a, b: int): bool =
  ## returns true if a+b overflows
  {.keepOverflowFlag.}:
    let x = a + b
    result = overflowFlag()

proc mulChecked(a, b: int): bool =
  {.keepOverflowFlag.}:
    let x = a * b
    result = overflowFlag()

proc main =
  echo "high+1 overflow: ", addChecked(high(int), 1)
  echo "low-1 overflow: ", addChecked(low(int), -1)
  echo "1+1 overflow: ", addChecked(1, 1)
  echo "small*small overflow: ", mulChecked(1000, 1000)
  echo "mid*mid overflow: ", mulChecked(1000000, 1000)

  # unsigned wraparound is well-defined (mod 2^64)
  let umax = high(uint)
  let wrapped = umax + 1'u
  echo "uint max+1 = ", wrapped
  let under = 0'u - 1'u
  echo "uint 0-1 = ", (under == umax)

  # bit operations, deterministic
  let a = 0b1100'u32
  let b = 0b1010'u32
  echo "and=", (a and b)
  echo "or=", (a or b)
  echo "xor=", (a xor b)
  echo "shl=", (1'u32 shl 8)
  echo "shr=", (256'u32 shr 4)

