import std/[syncio, strutils]

const Path = "/tmp/r12_fileio_data.txt"

proc main =
  let lines = @[
    "apple 3",
    "banana 7",
    "cherry 2",
    "date 5",
    "apple 4"
  ]
  var content = ""
  for ln in lines:
    content.add(ln)
    content.add("\n")

  try:
    writeFile(Path, content)
  except:
    echo "write failed"
    return

  # read it back line by line and total quantities per fruit (in first-seen order)
  var names: seq[string] = @[]
  var totals: seq[int] = @[]
  try:
    let text = readFile(Path)
    for ln in text.splitLines():
      let trimmed = ln.strip()
      if trimmed.len == 0: continue
      let parts = trimmed.splitWhitespace()
      if parts.len != 2: continue
      let name = parts[0]
      let qty = parseInt(parts[1])
      var idx = -1
      for i in 0 ..< names.len:
        if names[i] == name: idx = i
      if idx < 0:
        names.add(name)
        totals.add(qty)
      else:
        totals[idx] = totals[idx] + qty
  except:
    echo "read/parse failed"
    return

  echo "totals:"
  for i in 0 ..< names.len:
    echo "  ", names[i], " = ", totals[i]

  var grand = 0
  for t in totals: grand = grand + t
  echo "grand total = ", grand

  # cleanup: truncate the temp file to empty
  try:
    writeFile(Path, "")
    echo "cleaned up"
  except:
    echo "cleanup failed"

main()
